#!/usr/bin/env python3
# One-off repair for data/twitter/: the fw_begin.bin/fw_adjacent.bin/bw_*/undirected_*
# files GIR's loader actually reads were generated by a broken conversion pass (raw,
# uncompacted Twitter user IDs used directly as CSR indices -- vert_count came out
# ~equal to edge_count instead of the true ~41.7M active vertices). twitter.bin,
# sitting unused in the same directory, turns out to already be a correct, fully
# compacted CSR (verified: header V=41652231, E=1468365182 -- exactly DZiG's cited
# Twitter/Kwak-2010 numbers; begin array monotonic, ends at E; csr values in [0,V)).
# This rebuilds GIR's expected 6-file layout from that reliable source instead of
# trying to patch the broken ones.
import numpy as np
import os

SRC = "/home/cxl6029/projects/GIR/data/twitter/twitter.bin"
OUT_DIR = "/home/cxl6029/projects/GIR/data/twitter/_rebuilt"
os.makedirs(OUT_DIR, exist_ok=True)

print("Reading header...", flush=True)
header = np.fromfile(SRC, dtype=np.int64, count=3, offset=0)
V, E, total_bytes = int(header[0]), int(header[1]), int(header[2])
print(f"V={V} E={E} total_bytes={total_bytes}", flush=True)

begin_offset = 24
begin_count = V + 1
begin64 = np.memmap(SRC, dtype=np.int64, mode='r', offset=begin_offset, shape=(begin_count,))
assert begin64[-1] == E, "begin array doesn't end at E -- source file assumption violated"

csr_offset = begin_offset + begin_count * 8
csr = np.memmap(SRC, dtype=np.int32, mode='r', offset=csr_offset, shape=(E,))
assert csr_offset + E * 4 == total_bytes, "csr array doesn't fill out the rest of the file"

print("Writing fw_begin.bin (int32 downcast of begin64)...", flush=True)
begin32 = begin64.astype(np.int32)
begin32.tofile(os.path.join(OUT_DIR, "fw_begin.bin"))

print("Writing fw_adjacent.bin (direct copy of csr)...", flush=True)
# materialize once, reused below for the transpose and for the undirected copy
csr_arr = np.array(csr)
csr_arr.tofile(os.path.join(OUT_DIR, "fw_adjacent.bin"))

print("Copying fw_* as undirected_* (matches existing codebase convention: "
      "GIR's buildBCT() symmetrizes an asymmetric undirected CSR internally)...", flush=True)
begin32.tofile(os.path.join(OUT_DIR, "undirected_begin.bin"))
csr_arr.tofile(os.path.join(OUT_DIR, "undirected_adjacent.bin"))

print("Building transpose (bw_*) via sort-by-target...", flush=True)
degree = np.diff(begin64).astype(np.int64)
sources = np.repeat(np.arange(V, dtype=np.int32), degree)
assert sources.shape[0] == E

in_degree = np.bincount(csr_arr, minlength=V)
bw_begin64 = np.zeros(V + 1, dtype=np.int64)
np.cumsum(in_degree, out=bw_begin64[1:])
assert int(bw_begin64[-1]) == E

print("Sorting by target (this is the expensive step)...", flush=True)
order = np.argsort(csr_arr, kind='stable')
bw_adjacent = sources[order]
del order

bw_begin32 = bw_begin64.astype(np.int32)
bw_begin32.tofile(os.path.join(OUT_DIR, "bw_begin.bin"))
bw_adjacent.tofile(os.path.join(OUT_DIR, "bw_adjacent.bin"))

print("Done. Verifying output file sizes...", flush=True)
for fn in ["fw_begin.bin", "fw_adjacent.bin", "bw_begin.bin", "bw_adjacent.bin",
           "undirected_begin.bin", "undirected_adjacent.bin"]:
    p = os.path.join(OUT_DIR, fn)
    print(fn, os.path.getsize(p), "bytes")

print(f"Expected: begin files = {(V+1)*4} bytes, adjacent files = {E*4} bytes")
print("REBUILD COMPLETE")
